const uid=(p='id')=>`${p}_${Date.now()}_${Math.random().toString(36).slice(2,7)}`;
const clone=v=>JSON.parse(JSON.stringify(v));
const isHex=v=>/^#[0-9a-fA-F]{6}$/.test(v||'');
const getByPath=(obj,path)=>path.split('.').reduce((a,k)=>a?.[k],obj);
const setByPath=(obj,path,value)=>{const next=clone(obj);const parts=path.split('.');let cur=next;parts.forEach((k,i)=>{if(i===parts.length-1)cur[k]=value;else{cur[k]??={};cur=cur[k]}});return next};

