function mergeConfig(saved){
 const s=saved||{};return {...clone(defaultConfig),...s,header:{...defaultConfig.header,...(s.header||{})},logo:{...defaultConfig.logo,...(s.logo||{})},search:{...defaultConfig.search,...(s.search||{})},nav:{...defaultConfig.nav,...(s.nav||{})},cardDefaults:{...defaultConfig.cardDefaults,...(s.cardDefaults||{})},cardOverrides:s.cardOverrides||{},cardOrder:s.cardOrder||[],layout:Array.isArray(s.layout)&&s.layout.length?s.layout:clone(defaultLayout)};
}
function readLS(key,fallback){try{const x=JSON.parse(localStorage.getItem(key)||'null');return x??clone(fallback)}catch{return clone(fallback)}}

function useStore(){
 const legacyProducts=()=>readLS('ac_products',seedProducts);
 const legacyPromos=()=>readLS('ac_promos',defaultPromos);
 const [publishedProducts,setPublishedProducts]=useState(()=>readLS('ac_products_published',legacyProducts()));
 const [draftProducts,setDraftProducts]=useState(()=>readLS('ac_products_draft',legacyProducts()));
 const [publishedPromos,setPublishedPromos]=useState(()=>readLS('ac_promos_published',legacyPromos()));
 const [draftPromos,setDraftPromos]=useState(()=>readLS('ac_promos_draft',legacyPromos()));
 const [published,setPublished]=useState(()=>mergeConfig(readLS('ac_published',defaultConfig)));
 const [draft,setDraft]=useState(()=>mergeConfig(readLS('ac_draft',defaultConfig)));
 const [structures,setStructures]=useState(()=>readLS('ac_structures',defaultStructures));
 const [versions,setVersions]=useState(()=>readLS('ac_versions',[]));
 const [analytics,setAnalytics]=useState(()=>readLS('ac_analytics',{views:{},searches:{},departments:{},categories:{},promotions:{}}));
 useEffect(()=>localStorage.setItem('ac_products_published',JSON.stringify(publishedProducts)),[publishedProducts]);
 useEffect(()=>localStorage.setItem('ac_products_draft',JSON.stringify(draftProducts)),[draftProducts]);
 useEffect(()=>localStorage.setItem('ac_promos_published',JSON.stringify(publishedPromos)),[publishedPromos]);
 useEffect(()=>localStorage.setItem('ac_promos_draft',JSON.stringify(draftPromos)),[draftPromos]);
 useEffect(()=>localStorage.setItem('ac_published',JSON.stringify(published)),[published]);
 useEffect(()=>localStorage.setItem('ac_draft',JSON.stringify(draft)),[draft]);
 useEffect(()=>localStorage.setItem('ac_structures',JSON.stringify(structures)),[structures]);
 useEffect(()=>localStorage.setItem('ac_versions',JSON.stringify(versions)),[versions]);
 useEffect(()=>localStorage.setItem('ac_analytics',JSON.stringify(analytics)),[analytics]);
 const publishAll=()=>{
  const version={id:uid('v'),createdAt:new Date().toISOString(),config:clone(draft),products:clone(draftProducts),promos:clone(draftPromos)};
  setVersions(v=>[version,...v].slice(0,20));setPublished(clone(draft));setPublishedProducts(clone(draftProducts));setPublishedPromos(clone(draftPromos));
 };
 const discardAll=()=>{setDraft(clone(published));setDraftProducts(clone(publishedProducts));setDraftPromos(clone(publishedPromos))};
 return {publishedProducts,setPublishedProducts,draftProducts,setDraftProducts,publishedPromos,setPublishedPromos,draftPromos,setDraftPromos,published,setPublished,draft,setDraft,structures,setStructures,versions,setVersions,analytics,setAnalytics,publishAll,discardAll};
}

function track(setAnalytics,type,key){if(!key)return;setAnalytics(a=>({...a,[type]:{...(a[type]||{}),[key]:((a[type]||{})[key]||0)+1}}));}
function money(v){return v?`R$ ${v}`:''}
function readFile(file){return new Promise(res=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.readAsDataURL(file)})}
function reorder(arr,fromId,toId,key='id'){const copy=[...arr];const fi=copy.findIndex(x=>(typeof x==='string'?x:x[key])===fromId);const ti=copy.findIndex(x=>(typeof x==='string'?x:x[key])===toId);if(fi<0||ti<0||fi===ti)return copy;const [m]=copy.splice(fi,1);copy.splice(ti,0,m);return copy}

function SeasonalFx({theme,enabled,intensity=18}){const preset=themePresets[theme]||themePresets['Padrão'];if(!enabled||preset.fx==='none')return null;return <div className={`season-fx fx-${preset.fx}`} aria-hidden>{Array.from({length:Math.max(8,Math.min(50,Number(intensity)||18))}).map((_,i)=><span key={i} style={{left:`${(i*37)%100}%`,animationDelay:`${(i%9)*.31}s`,animationDuration:`${5+(i%6)}s`}}>{preset.symbols[i%preset.symbols.length]}</span>)}</div>}

function EditableTarget({editorMode,id,label,onSelect,selected,children,draggable=false,onDragStart,onDrop,className=''}){
 if(!editorMode)return children;
 return <div className={`edit-target ${selected?'selected':''} ${className}`} onClick={e=>{e.preventDefault();e.stopPropagation();onSelect?.(id)}} draggable={draggable} onDragStart={e=>{e.stopPropagation();onDragStart?.(e,id)}} onDragOver={e=>draggable&&e.preventDefault()} onDrop={e=>{e.preventDefault();e.stopPropagation();onDrop?.(e,id)}}>
  <div className="edit-chip"><MousePointer2 size={12}/>{label}</div><button className="edit-dots" onClick={e=>{e.preventDefault();e.stopPropagation();onSelect?.(id)}}><MoreVertical size={16}/></button>{draggable&&<div className="drag-handle"><GripVertical size={15}/></div>}{children}
 </div>
}

function applyFavicon(src){let link=document.querySelector("link[rel~='icon']");if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}if(src)link.href=src}

function PublicPortal({store,preview=false,configOverride,editorMode=false,onSelect,selectedId,onReorderBlock,onReorderCard}){
 const cfg=configOverride||store.published;const products=preview?store.draftProducts:store.publishedProducts;const promos=preview?store.draftPromos:store.publishedPromos;const {setAnalytics}=store;
 const [q,setQ]=useState('');const [selected,setSelected]=useState(null);const [dept,setDept]=useState('Todos');
 useEffect(()=>{if(!editorMode)applyFavicon(cfg.faviconImage)},[cfg.faviconImage,editorMode]);
 const departments=['Todos',...new Set(products.map(p=>p.department).filter(Boolean))];
 const orderedProducts=useMemo(()=>{const order=cfg.cardOrder||[];return [...products].sort((a,b)=>{const ai=order.indexOf(a.code),bi=order.indexOf(b.code);return (ai<0?99999:ai)-(bi<0?99999:bi)})},[products,cfg.cardOrder]);
 const filtered=orderedProducts.filter(p=>(dept==='Todos'||p.department===dept)&&([p.name,p.brand,p.code,p.department,p.category,p.section,p.subcategory,p.distribution].join(' ').toLowerCase().includes(q.toLowerCase())));
 const onSearch=v=>{setQ(v);if(!editorMode&&v.trim().length>=2)track(setAnalytics,'searches',v.trim().toLowerCase())};
 const style={'--primary':cfg.primary,'--secondary':cfg.secondary,'--bg':cfg.background,'--card':cfg.card,'--text':cfg.text,'--accent':cfg.accent,fontFamily:cfg.font,fontSize:`${cfg.baseFontSize||16}px`};
 const select=id=>onSelect?.(id);
 const onBlockDrag=(e,id)=>e.dataTransfer.setData('text/plain',`block:${id}`);
 const onBlockDrop=(e,id)=>{const raw=e.dataTransfer.getData('text/plain');if(raw.startsWith('block:'))onReorderBlock?.(raw.slice(6),id)};
 const onCardDrag=(e,id)=>e.dataTransfer.setData('text/plain',`card:${id}`);
 const onCardDrop=(e,id)=>{const raw=e.dataTransfer.getData('text/plain');if(raw.startsWith('card:'))onReorderCard?.(raw.slice(5),id)};
 return <div className={`portal ${editorMode?'portal-editor-mode':''}`} style={style}>
  {cfg.customCss&&<style>{cfg.customCss}</style>}<SeasonalFx theme={cfg.theme} enabled={cfg.seasonFx} intensity={cfg.fxIntensity}/>
  {preview&&<div className="preview-badge">PRÉ-VISUALIZAÇÃO — rascunho não publicado</div>}
  <EditableTarget editorMode={editorMode} id="header" label="Cabeçalho" onSelect={select} selected={selectedId==='header'}>
   <header className="public-header" style={{height:cfg.header.height,background:cfg.header.bg,color:cfg.header.text,position:cfg.header.sticky?'sticky':'relative',paddingLeft:cfg.header.paddingX,paddingRight:cfg.header.paddingX}}>
    <EditableTarget editorMode={editorMode} id="logo" label="Logo" onSelect={select} selected={selectedId==='logo'}>
     <div className="brand" style={{fontSize:cfg.logo.fontSize,minWidth:cfg.logo.width,height:cfg.logo.height}}>{cfg.logoImage?<img className="brand-img" src={cfg.logoImage} style={{width:cfg.logo.width,height:cfg.logo.height,objectFit:cfg.logo.fit}}/>:<span className="brand-symbol">◈</span>}{cfg.showBrandText&&<strong>{cfg.brand}</strong>}</div>
    </EditableTarget>
    <EditableTarget editorMode={editorMode} id="search" label="Pesquisa" onSelect={select} selected={selectedId==='search'}>
     <div className="searchbox" style={{width:`${cfg.search.width}%`,maxWidth:cfg.search.maxWidth,height:cfg.search.height,borderRadius:cfg.search.radius,background:cfg.search.bg,color:cfg.search.text,border:`1px solid ${cfg.search.border}`,fontSize:cfg.search.fontSize}}><Search size={18}/><input value={q} onChange={e=>onSearch(e.target.value)} placeholder={cfg.search.placeholder}/></div>
    </EditableTarget>
    {cfg.nav.show&&<EditableTarget editorMode={editorMode} id="nav" label="Menu" onSelect={select} selected={selectedId==='nav'}><nav style={{gap:cfg.nav.gap,fontSize:cfg.nav.fontSize}}><a href="#promo">Promoções</a><a href="#catalogo">Catálogo</a></nav></EditableTarget>}
   </header>
  </EditableTarget>
  <EditableTarget editorMode={editorMode} id="departments" label="Departamentos" onSelect={select} selected={selectedId==='departments'}><div className="deptbar">{departments.map(d=><button key={d} className={dept===d?'active':''} onClick={e=>{if(editorMode){e.preventDefault();return}setDept(d);if(d!=='Todos')track(setAnalytics,'departments',d)}}>{d}</button>)}</div></EditableTarget>
  <main>{cfg.layout.map(block=><EditableTarget key={block.id} editorMode={editorMode} id={`block:${block.id}`} label={block.type==='banner'?'Banner':block.type==='text'?'Texto':block.type==='manualCards'?'Cards':block.type==='catalog'?'Catálogo':block.type==='promotions'?'Promoções':'Bloco'} onSelect={select} selected={selectedId===`block:${block.id}`} draggable onDragStart={onBlockDrag} onDrop={onBlockDrop} className="block-edit-target">
   <RenderBlock block={block} cfg={cfg} products={filtered} allProducts={products} promos={promos} setSelected={setSelected} setAnalytics={setAnalytics} editorMode={editorMode} onSelect={select} selectedId={selectedId} onCardDrag={onCardDrag} onCardDrop={onCardDrop}/>
  </EditableTarget>)}</main>
  <EditableTarget editorMode={editorMode} id="footer" label="Rodapé" onSelect={select} selected={selectedId==='footer'}><footer>© {new Date().getFullYear()} {cfg.brand} • Catálogo digital</footer></EditableTarget>
  {selected&&!editorMode&&<ProductModal p={selected} onClose={()=>setSelected(null)}/>} 
 </div>
}

function RenderBlock({block,cfg,products,allProducts,promos,setSelected,setAnalytics,editorMode,onSelect,selectedId,onCardDrag,onCardDrop}){
 if(block.type==='banner')return <section className={`hero banner-${block.variant||'hero-split'}`} style={{minHeight:block.height||340,borderRadius:block.radius??22,background:block.image?`linear-gradient(rgba(0,0,0,${(block.overlay??20)/100}),rgba(0,0,0,${(block.overlay??20)/100})),url(${block.image}) center/cover`:block.bg||cfg.primary,color:block.text||'#fff',textAlign:block.align||'left'}}><div className="hero-copy"><small>{cfg.theme!=='Padrão'?`Tema ${cfg.theme} ativo`:'CATÁLOGO DIGITAL'}</small><h1>{block.title}</h1><p>{block.subtitle}</p>{block.cta&&<button style={{background:block.buttonBg||cfg.accent,color:block.buttonText||'#111'}}>{block.cta}</button>}</div>{block.variant==='hero-split'&&!block.image&&<div className="hero-orb">OFERTAS<br/><b>EM DESTAQUE</b></div>}</section>;
 if(block.type==='text')return <section className="text-block" style={{background:block.bg||'transparent',color:block.text||cfg.text,textAlign:block.align||'left',padding:`${block.padding??24}px`,borderRadius:block.radius??12,maxWidth:block.maxWidth?`${block.maxWidth}px`:'none',marginLeft:block.alignBox==='center'?'auto':0,marginRight:block.alignBox==='center'?'auto':0}}><h2 style={{fontSize:block.titleSize||28,fontFamily:block.font||cfg.font}}>{block.title}</h2><p style={{fontSize:block.bodySize||16,lineHeight:block.lineHeight||1.6,fontFamily:block.font||cfg.font}}>{block.body}</p></section>;
 if(block.type==='quick')return <section className="quick">{(block.items||[]).map((x,i)=><div key={i}>{x}</div>)}</section>;
 if(block.type==='manualCards')return <section><div className="section-head"><h2>{block.title||'Destaques'}</h2><span>{block.subtitle||''}</span></div><div className={`manual-grid card-template-${block.variant||'image-top'}`} style={{gridTemplateColumns:`repeat(${block.columns||3},minmax(0,1fr))`,gap:block.gap||14}}>{(block.cards||[]).map((c,i)=><EditableTarget key={c.id||i} editorMode={editorMode} id={`manual-card:${block.id}:${i}`} label={`Card ${i+1}`} onSelect={onSelect} selected={selectedId===`manual-card:${block.id}:${i}`}><article className="manual-card" style={{background:c.bg||cfg.card,color:c.text||cfg.text,borderRadius:c.radius??14,textAlign:c.align||'left'}}>{c.image&&c.imageVisible!==false&&<img src={c.image}/>}<div className="manual-card-body"><h3 style={{fontSize:c.titleSize||20}}>{c.title||'Novo card'}</h3><p>{c.subtitle||'Clique para editar este card individualmente.'}</p>{c.buttonText&&<button>{c.buttonText}</button>}</div></article></EditableTarget>)}</div></section>;
 if(block.type==='promotions')return <section id="promo"><div className="section-head"><h2>{block.title||'Promoções'}</h2><span>{block.subtitle||''}</span></div>{promos.filter(x=>x.active).map(pr=><div key={pr.id}><h3 className="promo-title" onClick={()=>!editorMode&&track(setAnalytics,'promotions',pr.name)}>{pr.name}</h3><div className="grid" style={{gridTemplateColumns:`repeat(${block.columns||6},minmax(0,1fr))`,gap:block.gap||14}}>{allProducts.filter(p=>pr.products.includes(p.code)).map(p=><ProductCard key={p.code} p={p} cfg={cfg} editorMode={editorMode} selected={selectedId===`card:${p.code}`} onSelect={()=>onSelect?.(`card:${p.code}`)} onOpen={()=>{setSelected(p);track(setAnalytics,'views',p.code)}} onDragStart={onCardDrag} onDrop={onCardDrop}/>)}</div></div>)}</section>;
 if(block.type==='catalog')return <section id="catalogo"><div className="section-head"><h2>{block.title||'Catálogo completo'}</h2><span>{products.length} produtos</span></div><div className="grid" style={{gridTemplateColumns:`repeat(${block.columns||6},minmax(0,1fr))`,gap:block.gap||14}}>{products.map(p=><ProductCard key={p.code} p={p} cfg={cfg} editorMode={editorMode} selected={selectedId===`card:${p.code}`} onSelect={()=>onSelect?.(`card:${p.code}`)} onOpen={()=>{setSelected(p);track(setAnalytics,'views',p.code)}} onDragStart={onCardDrag} onDrop={onCardDrop}/>)}</div></section>;
 return null;
}

function ProductCard({p,cfg,onOpen,editorMode,selected,onSelect,onDragStart,onDrop}){const o={...cfg.cardDefaults,...(cfg.cardOverrides?.[p.code]||{})};return <EditableTarget editorMode={editorMode} id={`card:${p.code}`} label={p.name} onSelect={onSelect} selected={selected} draggable onDragStart={(e)=>onDragStart?.(e,p.code)} onDrop={(e)=>onDrop?.(e,p.code)}><article className="product-card" style={{background:o.bg,color:o.text,borderRadius:o.radius,borderColor:o.border,boxShadow:o.shadow?'0 5px 20px #14213d18':'none',textAlign:o.align,gridColumn:`span ${o.span||1}`}}>{o.imageVisible!==false&&<div className="product-image" style={{height:o.imageHeight}}>{p.image?<img src={p.image} alt=""/>:<div className="no-image"><ImageOff size={28}/><span>Sem imagem</span></div>}</div>}<button className="product-title" style={{fontSize:o.titleSize,color:o.text,textAlign:o.align}} onClick={e=>{if(editorMode){e.preventDefault();onSelect?.()}else onOpen?.()}}>{p.name}</button>{o.showCrumb!==false&&<div className="crumb">{p.department} › {p.category} › {p.section}</div>}{o.showBrand!==false&&<div className="brandline">{p.brand}</div>}{p.showPrice&&<strong className="price">{money(p.price)}</strong>}{o.showButton!==false&&<button className={`details ${o.buttonStyle==='solid'?'solid':''}`} onClick={e=>{if(editorMode){e.preventDefault();onSelect?.()}else onOpen?.()}}>{o.buttonText||'Ver informações'}</button>}</article></EditableTarget>}
function ProductModal({p,onClose}){const d=p.details||{};return <div className="modal-back" onClick={onClose}><div className="modal" onClick={e=>e.stopPropagation()}><button className="close" onClick={onClose}><X/></button>{p.image?<img src={p.image}/>:<div className="modal-no-image"><ImageOff/></div>}<div><h2>{p.name}</h2>{d.brand!==false&&<p><b>Marca:</b> {p.brand}</p>}{d.code!==false&&<p><b>Código:</b> {p.code}</p>}{d.department&&<p><b>Localização:</b> {p.department} › {p.category} › {p.section} › {p.subcategory}</p>}{p.showPrice&&<h3>{money(p.price)}</h3>}<p>As informações exibidas nesta ficha são configuráveis pelo administrador.</p></div></div></div>}

function AdminApp({store}){const [logged,setLogged]=useState(()=>localStorage.getItem('ac_admin')==='1');const [page,setPage]=useState('Dashboard');if(!logged)return <Login onLogin={()=>{localStorage.setItem('ac_admin','1');setLogged(true)}}/>;const menu=[['Dashboard',LayoutDashboard],['Editor Visual',Palette],['Produtos',Package],['Estrutura',FolderTree],['Promoções',Percent],['Importações',Upload],['Temas',Sparkles],['Analytics',BarChart3],['Configurações',Settings]];return <div className="admin-shell"><aside><div className="admin-logo">◈ ASTERYON<small>CATÁLOGO ADMIN</small></div>{menu.map(([n,I])=><button className={page===n?'active':''} onClick={()=>setPage(n)} key={n}><I size={18}/>{n}</button>)}<button onClick={()=>{localStorage.removeItem('ac_admin');setLogged(false)}}><LogOut size={18}/>Sair</button></aside><section className="admin-main"><AdminTop title={page}/>{page==='Dashboard'&&<Dashboard store={store}/>} {page==='Editor Visual'&&<VisualEditor store={store}/>} {page==='Produtos'&&<ProductsAdmin store={store}/>} {page==='Estrutura'&&<StructureAdmin store={store}/>} {page==='Promoções'&&<PromotionsAdmin store={store}/>} {page==='Importações'&&<ImportsAdmin store={store}/>} {page==='Temas'&&<ThemesAdmin store={store}/>} {page==='Analytics'&&<Analytics store={store}/>} {page==='Configurações'&&<SettingsAdmin store={store}/>}</section></div>}
function Login({onLogin}){const [email,setEmail]=useState('admin@empresa.com.br'),[pass,setPass]=useState('demo123');return <div className="login"><div className="login-card"><div className="login-mark">◈</div><h1>ASTERYON</h1><p>Painel Administrativo</p><label>E-mail<input value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Senha<input type="password" value={pass} onChange={e=>setPass(e.target.value)}/></label><button onClick={onLogin}>Entrar no modo demonstração</button><small>Protótipo local. Em produção, substituir por Supabase Auth.</small></div></div>}
function AdminTop({title}){return <div className="admin-top"><div><h1>{title}</h1><p>Painel de gestão do catálogo</p></div><a href="/" target="_blank"><Eye size={17}/> Ver portal público</a></div>}
function Dashboard({store}){const {analytics,draftProducts,draftPromos,versions}=store;const views=Object.values(analytics.views||{}).reduce((a,b)=>a+b,0),searches=Object.values(analytics.searches||{}).reduce((a,b)=>a+b,0);return <div className="pad"><div className="metrics"><Metric n={views} t="Visualizações de produtos"/><Metric n={searches} t="Pesquisas"/><Metric n={draftProducts.length} t="Produtos no rascunho"/><Metric n={draftPromos.length} t="Promoções"/></div><div className="two"><Panel title="Produtos mais acessados"><Ranking obj={analytics.views} labels={Object.fromEntries(draftProducts.map(p=>[p.code,p.name]))}/></Panel><Panel title="Pesquisas mais realizadas"><Ranking obj={analytics.searches}/></Panel></div><div className="notice"><CheckCircle2/> O Portal Público continua exibindo somente a última versão publicada. Editor, produtos e promoções ficam em rascunho até a publicação.</div>{versions.length>0&&<Panel title="Últimas versões publicadas"><div className="version-list">{versions.slice(0,5).map((v,i)=><div key={v.id}><b>Versão {versions.length-i}</b><span>{new Date(v.createdAt).toLocaleString('pt-BR')}</span></div>)}</div></Panel>}</div>}
function Metric({n,t}){return <div className="metric"><strong>{Number(n||0).toLocaleString('pt-BR')}</strong><span>{t}</span></div>}
function Panel({title,children}){return <div className="panel"><h3>{title}</h3>{children}</div>}
function Ranking({obj={},labels={}}){const rows=Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,8);return rows.length?<ol className="ranking">{rows.map(([k,v])=><li key={k}><span>{labels[k]||k}</span><b>{v}</b></li>)}</ol>:<p className="muted">Ainda não há dados. Navegue no portal para gerar acessos.</p>}

function VisualEditor({store}){const {draft,setDraft,published,publishAll,discardAll,draftProducts}=store;const [device,setDevice]=useState('desktop');const [selectedId,setSelectedId]=useState('header');const [library,setLibrary]=useState(false);const [saved,setSaved]=useState(false);
 const updatePath=(path,value)=>setDraft(d=>setByPath(d,path,value));
 const updateLayoutBlock=(id,patch)=>setDraft(d=>({...d,layout:d.layout.map(b=>b.id===id?{...b,...patch}:b)}));
 const removeBlock=id=>setDraft(d=>({...d,layout:d.layout.filter(b=>b.id!==id)}));
 const addBlock=(type,variant)=>{let b;if(type==='banner')b={id:uid('banner'),type:'banner',variant,title:'Novo banner',subtitle:'Clique para editar o conteúdo.',cta:'Saiba mais',height:variant==='strip'?180:320,radius:16,image:'',imageVisible:true,align:'left',bg:draft.primary,text:'#ffffff',buttonBg:draft.accent,buttonText:'#111111',overlay:20};else if(type==='text')b={id:uid('text'),type:'text',title:'Novo título',body:'Adicione aqui qualquer texto institucional, chamada, aviso ou conteúdo livre.',titleSize:30,bodySize:16,lineHeight:1.6,padding:28,radius:12,bg:'#ffffff',text:draft.text,align:'left',alignBox:'stretch',font:draft.font};else b={id:uid('cards'),type:'manualCards',variant,title:'Destaques',subtitle:'Cards totalmente editáveis',columns:variant==='horizontal'?2:3,gap:14,cards:[0,1,2].map(i=>({id:uid('mc'),title:`Card ${i+1}`,subtitle:'Clique para editar individualmente',buttonText:'Ver mais',image:'',imageVisible:true,bg:'#ffffff',text:draft.text,radius:14,titleSize:20,align:'left',target:''}))};setDraft(d=>({...d,layout:[...d.layout,b]}));setLibrary(false);setSelectedId(`block:${b.id}`)};
 const reorderBlock=(from,to)=>setDraft(d=>({...d,layout:reorder(d.layout,from,to)}));
 const reorderCard=(from,to)=>setDraft(d=>{let order=[...(d.cardOrder||[])];draftProducts.forEach(p=>{if(!order.includes(p.code))order.push(p.code)});return {...d,cardOrder:reorder(order,from,to,'')}});
 const saveDraft=()=>{setSaved(true);setTimeout(()=>setSaved(false),1200)};
 return <div className="editor-layout"><div className="editor-toolbar"><div className="device"><button onClick={()=>setDevice('desktop')} className={device==='desktop'?'active':''}><Monitor size={17}/>Desktop</button><button onClick={()=>setDevice('tablet')} className={device==='tablet'?'active':''}><Tablet size={17}/>Tablet</button><button onClick={()=>setDevice('mobile')} className={device==='mobile'?'active':''}><Smartphone size={17}/>Celular</button></div><button onClick={()=>setLibrary(true)} className="add-tool"><Plus size={16}/>Adicionar</button><button onClick={saveDraft}><Save size={16}/>{saved?'Salvo':'Salvar rascunho'}</button><button className="ghost" onClick={()=>{if(confirm('Descartar todas as alterações não publicadas?'))discardAll()}}><Undo2 size={16}/>Descartar</button><button className="publish" onClick={()=>{publishAll();alert('Alterações publicadas no Portal Público.')}}><CheckCircle2 size={16}/>Publicar alterações</button></div><div className="editor-body"><div className={'preview-frame '+device}><PublicPortal store={store} preview configOverride={draft} editorMode onSelect={setSelectedId} selectedId={selectedId} onReorderBlock={reorderBlock} onReorderCard={reorderCard}/></div><EditorInspector store={store} selectedId={selectedId} setSelectedId={setSelectedId} updatePath={updatePath} updateLayoutBlock={updateLayoutBlock} removeBlock={removeBlock}/></div>{library&&<BlockLibrary onClose={()=>setLibrary(false)} onAdd={addBlock}/>}</div>}

function ColorControl({label,value,onChange}){const [txt,setTxt]=useState(value||'#000000');useEffect(()=>setTxt(value||'#000000'),[value]);return <label className="color-label">{label}<div className="color-row"><input type="color" value={isHex(value)?value:'#000000'} onChange={e=>{setTxt(e.target.value);onChange(e.target.value)}}/><input value={txt} onChange={e=>{setTxt(e.target.value);if(isHex(e.target.value))onChange(e.target.value)}} placeholder="#RRGGBB"/></div></label>}
function UploadControl({label,value,onChange,accept='image/*'}){return <div className="upload-control"><span>{label}</span>{value&&<div className="upload-preview"><img src={value}/><button onClick={()=>onChange('')} title="Remover imagem"><ImageOff size={15}/>Remover</button></div>}<label className="upload-button"><Upload size={15}/>Selecionar imagem<input hidden type="file" accept={accept} onChange={async e=>{const f=e.target.files?.[0];if(f)onChange(await readFile(f));e.target.value=''}}/></label></div>}
function NumberControl({label,value,onChange,min=0,max=2000,step=1,suffix='px'}){return <label>{label}<div className="number-row"><input type="range" min={min} max={max} step={step} value={Number(value)||0} onChange={e=>onChange(Number(e.target.value))}/><input type="number" min={min} max={max} step={step} value={Number(value)||0} onChange={e=>onChange(Number(e.target.value))}/><span>{suffix}</span></div></label>}

function EditorInspector({store,selectedId,setSelectedId,updatePath,updateLayoutBlock,removeBlock}){const {draft,setDraft,draftProducts,setDraftProducts}=store;const selectedBlock=selectedId?.startsWith('block:')?draft.layout.find(b=>b.id===selectedId.slice(6)):null;const selectedProduct=selectedId?.startsWith('card:')?draftProducts.find(p=>p.code===selectedId.slice(5)):null;const manualInfo=selectedId?.startsWith('manual-card:')?selectedId.split(':'):null;const manualBlock=manualInfo?draft.layout.find(b=>b.id===manualInfo[1]):null;const manualIndex=manualInfo?Number(manualInfo[2]):null;
 const updateManual=patch=>setDraft(d=>({...d,layout:d.layout.map(b=>b.id===manualBlock.id?{...b,cards:b.cards.map((c,i)=>i===manualIndex?{...c,...patch}:c)}:b)}));
 const updateCard=(key,value)=>setDraft(d=>({...d,cardOverrides:{...(d.cardOverrides||{}),[selectedProduct.code]:{...(d.cardOverrides?.[selectedProduct.code]||{}),[key]:value}}}));
 const cardCfg=selectedProduct?{...draft.cardDefaults,...(draft.cardOverrides?.[selectedProduct.code]||{})}:null;
 const deleteBlock=()=>{if(selectedBlock&&confirm('Excluir este bloco visual?')){removeBlock(selectedBlock.id);setSelectedId('header')}};
 return <aside className="props"><div className="props-title"><div><SlidersHorizontal size={18}/><b>Editar elemento</b></div><small>{selectedId}</small></div>
  {selectedId==='header'&&<><h4>Cabeçalho</h4><NumberControl label="Altura" value={draft.header.height} min={48} max={160} onChange={v=>updatePath('header.height',v)}/><ColorControl label="Cor de fundo" value={draft.header.bg} onChange={v=>updatePath('header.bg',v)}/><ColorControl label="Cor dos textos" value={draft.header.text} onChange={v=>updatePath('header.text',v)}/><NumberControl label="Margem lateral" value={draft.header.paddingX} min={0} max={120} onChange={v=>updatePath('header.paddingX',v)}/><label className="switch"><input type="checkbox" checked={draft.header.sticky} onChange={e=>updatePath('header.sticky',e.target.checked)}/> Cabeçalho fixo</label></>}
  {selectedId==='logo'&&<><h4>Logo e ícone da empresa</h4><UploadControl label="Logo da empresa" value={draft.logoImage} onChange={v=>updatePath('logoImage',v)}/><label>Nome da empresa<input value={draft.brand} onChange={e=>updatePath('brand',e.target.value)}/></label><label className="switch"><input type="checkbox" checked={draft.showBrandText} onChange={e=>updatePath('showBrandText',e.target.checked)}/> Mostrar nome ao lado da logo</label><NumberControl label="Largura da logo" value={draft.logo.width} min={40} max={420} onChange={v=>updatePath('logo.width',v)}/><NumberControl label="Altura da logo" value={draft.logo.height} min={24} max={140} onChange={v=>updatePath('logo.height',v)}/><NumberControl label="Tamanho do nome" value={draft.logo.fontSize} min={10} max={60} onChange={v=>updatePath('logo.fontSize',v)}/><UploadControl label="Ícone/Favicon" value={draft.faviconImage} onChange={v=>updatePath('faviconImage',v)} accept="image/png,image/x-icon,image/svg+xml"/></>}
  {selectedId==='search'&&<><h4>Barra de pesquisa</h4><label>Texto de ajuda<input value={draft.search.placeholder} onChange={e=>updatePath('search.placeholder',e.target.value)}/></label><NumberControl label="Largura" value={draft.search.width} min={20} max={100} onChange={v=>updatePath('search.width',v)} suffix="%"/><NumberControl label="Largura máxima" value={draft.search.maxWidth} min={200} max={1400} onChange={v=>updatePath('search.maxWidth',v)}/><NumberControl label="Altura" value={draft.search.height} min={30} max={90} onChange={v=>updatePath('search.height',v)}/><NumberControl label="Arredondamento" value={draft.search.radius} min={0} max={50} onChange={v=>updatePath('search.radius',v)}/><NumberControl label="Tamanho da letra" value={draft.search.fontSize} min={10} max={30} onChange={v=>updatePath('search.fontSize',v)}/><ColorControl label="Fundo" value={draft.search.bg} onChange={v=>updatePath('search.bg',v)}/><ColorControl label="Texto/ícone" value={draft.search.text} onChange={v=>updatePath('search.text',v)}/><ColorControl label="Borda" value={draft.search.border} onChange={v=>updatePath('search.border',v)}/></>}
  {selectedId==='nav'&&<><h4>Menu superior</h4><NumberControl label="Tamanho da letra" value={draft.nav.fontSize} min={10} max={28} onChange={v=>updatePath('nav.fontSize',v)}/><NumberControl label="Espaço entre itens" value={draft.nav.gap} min={0} max={60} onChange={v=>updatePath('nav.gap',v)}/><label className="switch"><input type="checkbox" checked={draft.nav.show} onChange={e=>updatePath('nav.show',e.target.checked)}/> Exibir menu</label></>}
  {selectedId==='departments'&&<><h4>Faixa de departamentos</h4><p className="muted">A organização é controlada na aba Estrutura. Aqui você ajusta o visual da faixa.</p><ColorControl label="Cor principal" value={draft.secondary} onChange={v=>updatePath('secondary',v)}/></>}
  {selectedBlock&&<BlockInspector block={selectedBlock} draft={draft} update={patch=>updateLayoutBlock(selectedBlock.id,patch)} onDelete={deleteBlock}/>} 
  {selectedProduct&&<><h4>Card individual</h4><div className="selected-product-name">{selectedProduct.name}<small>Código {selectedProduct.code}</small></div><NumberControl label="Largura do card (colunas)" value={cardCfg.span} min={1} max={3} onChange={v=>updateCard('span',v)} suffix="x"/><ColorControl label="Fundo do card" value={cardCfg.bg} onChange={v=>updateCard('bg',v)}/><ColorControl label="Cor do texto" value={cardCfg.text} onChange={v=>updateCard('text',v)}/><ColorControl label="Cor da borda" value={cardCfg.border} onChange={v=>updateCard('border',v)}/><NumberControl label="Arredondamento" value={cardCfg.radius} min={0} max={50} onChange={v=>updateCard('radius',v)}/><NumberControl label="Altura da imagem" value={cardCfg.imageHeight} min={0} max={420} onChange={v=>updateCard('imageHeight',v)}/><NumberControl label="Tamanho do título" value={cardCfg.titleSize} min={10} max={36} onChange={v=>updateCard('titleSize',v)}/><label>Alinhamento<select value={cardCfg.align} onChange={e=>updateCard('align',e.target.value)}><option value="left">Esquerda</option><option value="center">Centro</option><option value="right">Direita</option></select></label><label className="switch"><input type="checkbox" checked={cardCfg.imageVisible!==false} onChange={e=>updateCard('imageVisible',e.target.checked)}/> Exibir imagem</label><label className="switch"><input type="checkbox" checked={cardCfg.shadow!==false} onChange={e=>updateCard('shadow',e.target.checked)}/> Sombra</label><label className="switch"><input type="checkbox" checked={cardCfg.showBrand!==false} onChange={e=>updateCard('showBrand',e.target.checked)}/> Mostrar marca</label><label className="switch"><input type="checkbox" checked={cardCfg.showCrumb!==false} onChange={e=>updateCard('showCrumb',e.target.checked)}/> Mostrar caminho</label><label className="switch"><input type="checkbox" checked={cardCfg.showButton!==false} onChange={e=>updateCard('showButton',e.target.checked)}/> Mostrar botão</label><label>Texto do botão<input value={cardCfg.buttonText} onChange={e=>updateCard('buttonText',e.target.value)}/></label><label>Estilo do botão<select value={cardCfg.buttonStyle} onChange={e=>updateCard('buttonStyle',e.target.value)}><option value="outline">Contorno</option><option value="solid">Preenchido</option></select></label>{selectedProduct.image&&<button className="danger-action" onClick={()=>{if(confirm('Remover a imagem deste produto no rascunho?'))setDraftProducts(ps=>ps.map(p=>p.code===selectedProduct.code?{...p,image:''}:p))}}><ImageOff size={15}/>Remover imagem do produto</button>}<button className="secondary-action" onClick={()=>setDraft(d=>{const o={...(d.cardOverrides||{})};delete o[selectedProduct.code];return {...d,cardOverrides:o}})}><RefreshCw size={15}/>Restaurar estilo padrão deste card</button><p className="muted">Arraste o card diretamente no preview para mudar sua posição.</p></>}
  {manualBlock&&manualBlock.cards?.[manualIndex]&&<ManualCardInspector card={manualBlock.cards[manualIndex]} update={updateManual}/>} 
  {selectedId==='footer'&&<><h4>Rodapé</h4><p className="muted">O rodapé herda as cores e a marca globais. Uma versão futura pode receber blocos próprios.</p></>}
  {!selectedId&&<p className="muted">Clique em qualquer elemento da página. A barra lateral mostrará as opções daquele item.</p>}
 </aside>}

function BlockInspector({block,draft,update,onDelete}){if(block.type==='banner')return <><h4>Banner — {block.variant}</h4><label>Tipo de banner<select value={block.variant} onChange={e=>update({variant:e.target.value})}><option value="hero-split">Hero dividido</option><option value="full-image">Imagem total</option><option value="strip">Faixa</option><option value="minimal">Minimalista</option><option value="spotlight">Destaque central</option></select></label><label>Título<input value={block.title||''} onChange={e=>update({title:e.target.value})}/></label><label>Subtítulo<textarea value={block.subtitle||''} onChange={e=>update({subtitle:e.target.value})}/></label><label>Texto do botão<input value={block.cta||''} onChange={e=>update({cta:e.target.value})}/></label><UploadControl label="Imagem do banner" value={block.image} onChange={v=>update({image:v})}/><NumberControl label="Altura" value={block.height} min={100} max={700} onChange={v=>update({height:v})}/><NumberControl label="Arredondamento" value={block.radius} min={0} max={70} onChange={v=>update({radius:v})}/><NumberControl label="Escurecer imagem" value={block.overlay} min={0} max={90} onChange={v=>update({overlay:v})} suffix="%"/><ColorControl label="Fundo" value={block.bg} onChange={v=>update({bg:v})}/><ColorControl label="Texto" value={block.text} onChange={v=>update({text:v})}/><ColorControl label="Botão" value={block.buttonBg} onChange={v=>update({buttonBg:v})}/><ColorControl label="Texto do botão" value={block.buttonText} onChange={v=>update({buttonText:v})}/><label>Alinhamento<select value={block.align} onChange={e=>update({align:e.target.value})}><option value="left">Esquerda</option><option value="center">Centro</option><option value="right">Direita</option></select></label><button className="danger-action" onClick={onDelete}><Trash2 size={15}/>Excluir banner</button></>;
 if(block.type==='text')return <><h4>Caixa de texto</h4><label>Título<input value={block.title||''} onChange={e=>update({title:e.target.value})}/></label><label>Texto<textarea rows="6" value={block.body||''} onChange={e=>update({body:e.target.value})}/></label><label>Fonte<select value={block.font||draft.font} onChange={e=>update({font:e.target.value})}>{['Inter, system-ui, sans-serif','Arial, sans-serif','Georgia, serif','Trebuchet MS, sans-serif','Verdana, sans-serif'].map(x=><option key={x} value={x}>{x.split(',')[0]}</option>)}</select></label><NumberControl label="Título" value={block.titleSize} min={14} max={72} onChange={v=>update({titleSize:v})}/><NumberControl label="Texto" value={block.bodySize} min={10} max={40} onChange={v=>update({bodySize:v})}/><NumberControl label="Espaçamento interno" value={block.padding} min={0} max={100} onChange={v=>update({padding:v})}/><NumberControl label="Arredondamento" value={block.radius} min={0} max={60} onChange={v=>update({radius:v})}/><ColorControl label="Fundo" value={block.bg} onChange={v=>update({bg:v})}/><ColorControl label="Texto" value={block.text} onChange={v=>update({text:v})}/><label>Alinhamento<select value={block.align} onChange={e=>update({align:e.target.value})}><option value="left">Esquerda</option><option value="center">Centro</option><option value="right">Direita</option></select></label><button className="danger-action" onClick={onDelete}><Trash2 size={15}/>Excluir caixa de texto</button></>;
 if(block.type==='manualCards')return <><h4>Grupo de cards — {block.variant}</h4><label>Título<input value={block.title||''} onChange={e=>update({title:e.target.value})}/></label><label>Subtítulo<input value={block.subtitle||''} onChange={e=>update({subtitle:e.target.value})}/></label><label>Modelo<select value={block.variant} onChange={e=>update({variant:e.target.value})}><option value="image-top">Imagem superior</option><option value="horizontal">Horizontal</option><option value="minimal">Minimalista</option><option value="feature">Destaque</option></select></label><NumberControl label="Cards por linha" value={block.columns} min={1} max={6} onChange={v=>update({columns:v})} suffix=""/><NumberControl label="Espaço" value={block.gap} min={0} max={60} onChange={v=>update({gap:v})}/><button className="secondary-action" onClick={()=>update({cards:[...(block.cards||[]),{id:uid('mc'),title:'Novo card',subtitle:'Clique para editar',buttonText:'Ver mais',image:'',imageVisible:true,bg:'#ffffff',text:draft.text,radius:14,titleSize:20,align:'left',target:''}]})}><Plus size={15}/>Adicionar card</button><button className="danger-action" onClick={onDelete}><Trash2 size={15}/>Excluir grupo de cards</button><p className="muted">Clique em cada card no preview para editar separadamente.</p></>;
 if(block.type==='catalog'||block.type==='promotions')return <><h4>{block.type==='catalog'?'Catálogo':'Promoções'}</h4><label>Título<input value={block.title||''} onChange={e=>update({title:e.target.value})}/></label>{block.type==='promotions'&&<label>Subtítulo<input value={block.subtitle||''} onChange={e=>update({subtitle:e.target.value})}/></label>}<NumberControl label="Cards por linha" value={block.columns} min={1} max={8} onChange={v=>update({columns:v})} suffix=""/><NumberControl label="Espaço entre cards" value={block.gap} min={0} max={60} onChange={v=>update({gap:v})}/><button className="danger-action" onClick={onDelete}><Trash2 size={15}/>Excluir bloco</button></>;
 if(block.type==='quick')return <><h4>Faixa de benefícios</h4><p className="muted">Arraste para reposicionar. Você também pode excluir e adicionar outros tipos de bloco.</p><button className="danger-action" onClick={onDelete}><Trash2 size={15}/>Excluir bloco</button></>;
 return null}
function ManualCardInspector({card,update}){return <><h4>Card individual</h4><label>Título<input value={card.title||''} onChange={e=>update({title:e.target.value})}/></label><label>Subtítulo<textarea value={card.subtitle||''} onChange={e=>update({subtitle:e.target.value})}/></label><label>Texto do botão<input value={card.buttonText||''} onChange={e=>update({buttonText:e.target.value})}/></label><label>Destino do clique<input value={card.target||''} onChange={e=>update({target:e.target.value})} placeholder="Produto, categoria, promoção ou URL"/></label><UploadControl label="Imagem do card" value={card.image} onChange={v=>update({image:v})}/><ColorControl label="Fundo" value={card.bg} onChange={v=>update({bg:v})}/><ColorControl label="Texto" value={card.text} onChange={v=>update({text:v})}/><NumberControl label="Arredondamento" value={card.radius} min={0} max={60} onChange={v=>update({radius:v})}/><NumberControl label="Tamanho do título" value={card.titleSize} min={10} max={44} onChange={v=>update({titleSize:v})}/><label>Alinhamento<select value={card.align} onChange={e=>update({align:e.target.value})}><option value="left">Esquerda</option><option value="center">Centro</option><option value="right">Direita</option></select></label><label className="switch"><input type="checkbox" checked={card.imageVisible!==false} onChange={e=>update({imageVisible:e.target.checked})}/> Exibir imagem</label></>}

function BlockLibrary({onClose,onAdd}){return <div className="modal-back library-back" onClick={onClose}><div className="block-library" onClick={e=>e.stopPropagation()}><button className="close" onClick={onClose}><X/></button><h2>Adicionar ao site</h2><p>Escolha um modelo. Depois clique no elemento dentro do preview para personalizar tudo.</p><h3><GalleryHorizontal size={18}/> Banners sugeridos</h3><div className="library-grid">{[['hero-split','Hero dividido'],['full-image','Imagem total'],['strip','Faixa horizontal'],['minimal','Minimalista'],['spotlight','Destaque central']].map(([v,n])=><button key={v} onClick={()=>onAdd('banner',v)}><div className={`mini-banner ${v}`}></div><b>{n}</b><small>Totalmente editável</small></button>)}</div><h3><LayoutGrid size={18}/> Cards sugeridos</h3><div className="library-grid">{[['image-top','Imagem superior'],['horizontal','Horizontal'],['minimal','Minimalista'],['feature','Destaque']].map(([v,n])=><button key={v} onClick={()=>onAdd('cards',v)}><div className={`mini-cards ${v}`}><i/><i/><i/></div><b>{n}</b><small>Cards independentes</small></button>)}</div><h3><Type size={18}/> Conteúdo livre</h3><div className="library-grid one"><button onClick={()=>onAdd('text','text')}><Type/><b>Caixa de texto</b><small>Adicionar, editar, mover ou excluir</small></button></div></div></div>}

function ProductsAdmin({store}){const {draftProducts,setDraftProducts}=store;const products=draftProducts;const [selected,setSelected]=useState(products[0]||null);const [q,setQ]=useState('');const [dept,setDept]=useState('Todos');const [brand,setBrand]=useState('Todas');const [cat,setCat]=useState('Todas');const [priceFilter,setPriceFilter]=useState('Todos');const depts=['Todos',...new Set(products.map(p=>p.department).filter(Boolean))],brands=['Todas',...new Set(products.map(p=>p.brand).filter(Boolean))],cats=['Todas',...new Set(products.map(p=>p.category).filter(Boolean))];const rows=products.filter(p=>(dept==='Todos'||p.department===dept)&&(brand==='Todas'||p.brand===brand)&&(cat==='Todas'||p.category===cat)&&(priceFilter==='Todos'||(priceFilter==='Com preço'?p.showPrice:!p.showPrice))&&([p.code,p.name,p.brand,p.department,p.category,p.section].join(' ').toLowerCase().includes(q.toLowerCase())));const upd=(k,v)=>{setDraftProducts(ps=>ps.map(p=>p.code===selected.code?{...p,[k]:v}:p));setSelected(s=>({...s,[k]:v}))};return <div className="pad"><div className="product-filters"><div className="filter-search"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Código, produto, marca, categoria..."/></div><select value={dept} onChange={e=>setDept(e.target.value)}>{depts.map(x=><option key={x}>{x}</option>)}</select><select value={cat} onChange={e=>setCat(e.target.value)}>{cats.map(x=><option key={x}>{x}</option>)}</select><select value={brand} onChange={e=>setBrand(e.target.value)}>{brands.map(x=><option key={x}>{x}</option>)}</select><select value={priceFilter} onChange={e=>setPriceFilter(e.target.value)}><option>Todos</option><option>Com preço</option><option>Sem preço</option></select><span>{rows.length} resultados</span></div><div className="page-actions"><button onClick={()=>{const code=String(Date.now()).slice(-6);const p={code,name:'Novo produto',brand:'',department:'',category:'',section:'',subcategory:'',distribution:'',price:'',showPrice:false,image:'',details:{code:true,brand:true,department:true,description:true}};setDraftProducts([...products,p]);setSelected(p)}}><Plus size={16}/>Novo produto</button></div><div className="product-admin"><div className="table-wrap"><table><thead><tr><th>Código</th><th>Produto</th><th>Departamento</th><th>Categoria</th><th>Marca</th><th>Preço</th></tr></thead><tbody>{rows.map(p=><tr key={p.code} onClick={()=>setSelected(p)} className={selected?.code===p.code?'sel':''}><td>{p.code}</td><td>{p.name}</td><td>{p.department}</td><td>{p.category}</td><td>{p.brand}</td><td>{p.showPrice?money(p.price):'Oculto'}</td></tr>)}</tbody></table></div>{selected&&<div className="form-card"><h3>Editar produto</h3>{['code','name','brand','department','category','section','subcategory','distribution','price'].map(k=><label key={k}>{({code:'Código',name:'Descrição',brand:'Marca',department:'Departamento',category:'Categoria',section:'Seção',subcategory:'Subcategoria',distribution:'Distribuição',price:'Preço (opcional)'})[k]}<input value={selected[k]||''} onChange={e=>upd(k,e.target.value)}/></label>)}<UploadControl label="Imagem do produto" value={selected.image} onChange={v=>upd('image',v)}/><label className="switch"><input type="checkbox" checked={selected.showPrice} onChange={e=>upd('showPrice',e.target.checked)}/> Exibir preço</label><h4>Informações da ficha pública</h4>{[['code','Código'],['brand','Marca'],['department','Caminho/estrutura'],['description','Descrição']].map(([k,n])=><label className="switch" key={k}><input type="checkbox" checked={selected.details?.[k]!==false} onChange={e=>upd('details',{...(selected.details||{}),[k]:e.target.checked})}/> {n}</label>)}<p className="muted">Estas alterações ficam no rascunho. O portal só recebe os dados quando o ADMIN publicar.</p></div>}</div></div>}

function StructureAdmin({store}){const {structures,setStructures}=store;const addTree=()=>setStructures(s=>[...s,{id:uid('tree'),name:'Nova estrutura',children:[]}]);const updateNode=(id,patch)=>setStructures(ss=>ss.map(t=>t.id===id?{...t,...patch}:{...t,children:updateChildren(t.children,id,patch)}));const addChild=id=>setStructures(ss=>ss.map(t=>t.id===id?{...t,children:[...t.children,{id:uid('node'),name:'Novo nível',children:[]}]}:{...t,children:addChildRec(t.children,id)}));const del=id=>setStructures(ss=>ss.filter(t=>t.id!==id).map(t=>({...t,children:deleteRec(t.children,id)})));return <div className="pad"><div className="page-actions"><button onClick={addTree}><Plus size={16}/>Nova estrutura</button></div><div className="notice"><FolderTree/> Cada empresa pode criar sua própria árvore: departamentos, categorias, seções, subcategorias, distribuições, linhas, famílias ou qualquer outro nome. Não há limite fixo de níveis.</div><div className="structure-board">{structures.map(t=><StructureNode key={t.id} node={t} root onUpdate={updateNode} onAdd={addChild} onDelete={del}/>)}</div></div>}
function updateChildren(children,id,patch){return children.map(n=>n.id===id?{...n,...patch}:{...n,children:updateChildren(n.children||[],id,patch)})}
function addChildRec(children,id){return children.map(n=>n.id===id?{...n,children:[...(n.children||[]),{id:uid('node'),name:'Novo nível',children:[]}]}:{...n,children:addChildRec(n.children||[],id)})}
function deleteRec(children,id){return children.filter(n=>n.id!==id).map(n=>({...n,children:deleteRec(n.children||[],id)}))}
function StructureNode({node,root,onUpdate,onAdd,onDelete,depth=0}){const [open,setOpen]=useState(true);return <div className={`structure-node ${root?'root':''}`} style={{'--depth':depth}}><div className="structure-row"><button className="tree-toggle" onClick={()=>setOpen(o=>!o)}>{open?<ChevronDown size={15}/>:<ChevronRight size={15}/>}</button><input value={node.name} onChange={e=>onUpdate(node.id,{name:e.target.value})}/><span>{root?'Estrutura principal':'Nível livre'}</span><button onClick={()=>onAdd(node.id)} title="Adicionar subnível"><Plus size={15}/></button><button onClick={()=>{if(confirm(`Excluir “${node.name}” e seus subníveis?`))onDelete(node.id)}} title="Excluir"><Trash2 size={15}/></button></div>{open&&(node.children||[]).length>0&&<div className="structure-children">{node.children.map(c=><StructureNode key={c.id} node={c} onUpdate={onUpdate} onAdd={onAdd} onDelete={onDelete} depth={depth+1}/>)}</div>}</div>}

function PromotionsAdmin({store}){const {draftProducts:products,draftPromos:promos,setDraftPromos:setPromos}=store;const [name,setName]=useState('Nova promoção');const create=()=>setPromos([...promos,{id:uid('promo'),name,products:[],active:true}]);const toggle=(id,code)=>setPromos(ps=>ps.map(p=>p.id===id?{...p,products:p.products.includes(code)?p.products.filter(x=>x!==code):[...p.products,code]}:p));return <div className="pad"><div className="page-actions"><input value={name} onChange={e=>setName(e.target.value)}/><button onClick={create}><Plus size={16}/>Criar promoção</button></div>{promos.map(pr=><Panel key={pr.id} title={pr.name}><p className="muted">Promoções são a única área que pode misturar livremente produtos de departamentos, categorias, seções e subcategorias diferentes.</p><label className="switch"><input type="checkbox" checked={pr.active} onChange={e=>setPromos(ps=>ps.map(x=>x.id===pr.id?{...x,active:e.target.checked}:x))}/> Promoção ativa</label><div className="check-grid">{products.map(p=><label key={p.code}><input type="checkbox" checked={pr.products.includes(p.code)} onChange={()=>toggle(pr.id,p.code)}/>{p.name}<small>{p.department} › {p.category}</small></label>)}</div></Panel>)}</div>}

function ImportsAdmin({store}){const {draftProducts:products,setDraftProducts:setProducts}=store;const [report,setReport]=useState(null);async function importSheet(file){const buf=await file.arrayBuffer();const wb=XLSX.read(buf);const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});let created=0,updated=0;setProducts(prev=>{let next=[...prev];rows.forEach(r=>{const code=String(r.Codigo||r.CÓDIGO||r.CODIGO||r.codigo||r.codprod||r.CODPROD||'').trim();if(!code)return;const data={code,name:r.Descricao||r.DESCRICAO||r.descricao||r.Produto||r.PRODUTO||`Produto ${code}`,brand:r.Marca||r.MARCA||r.marca||'',department:r.Departamento||r.DEPARTAMENTO||r.Depto||r.DEPTO||'Sem departamento',category:r.Categoria||r.CATEGORIA||r.categoria||'Sem categoria',section:r.Secao||r.SECAO||r.Seção||r.SEÇÃO||'Sem seção',subcategory:r.Subcategoria||r.SUBCATEGORIA||'',distribution:r.Distribuicao||r.DISTRIBUICAO||r.Distribuição||r.DISTRIBUIÇÃO||'',price:String(r.Preco||r.PRECO||r.Preço||r.PREÇO||''),showPrice:false,image:'',details:{code:true,brand:true,department:true,description:true}};const idx=next.findIndex(p=>p.code===code);if(idx>=0){next[idx]={...next[idx],...data,image:next[idx].image};updated++}else{next.push(data);created++}});return next});setReport({type:'Planilha',created,updated,total:rows.length})}
 async function importImages(files){let linked=0,unlinked=0;const updates={};for(const file of files){const base=file.name.replace(/\.[^.]+$/,'');const code=base.split(/[_-]/)[0];if(!products.some(p=>p.code===code)){unlinked++;continue}updates[code]=await readFile(file);linked++}setProducts(ps=>ps.map(p=>updates[p.code]?{...p,image:updates[p.code]}:p));setReport({type:'Imagens',linked,unlinked,total:files.length})}
 return <div className="pad"><div className="two"><Panel title="Importar produtos Excel/CSV"><div className="drop"><FileSpreadsheet size={40}/><b>Envie .xlsx, .xls ou .csv</b><p>O código da planilha é preservado como código do produto.</p><input type="file" accept=".xlsx,.xls,.csv" onChange={e=>e.target.files[0]&&importSheet(e.target.files[0])}/></div></Panel><Panel title="Importar imagens"><div className="drop"><ImageIcon size={40}/><b>PNG/JPG pelo código do produto</b><p>Ex.: 10001.png, 10001_2.png. O vínculo é automático pelo nome do arquivo.</p><input type="file" accept="image/png,image/jpeg" multiple onChange={e=>importImages([...e.target.files])}/></div></Panel></div>{report&&<div className="report"><CheckCircle2/><div><b>Importação concluída: {report.type}</b><pre>{JSON.stringify(report,null,2)}</pre></div></div>}<div className="notice"><Save/> As importações atualizam o rascunho. Só chegam ao Portal Público quando o ADMIN publicar.</div></div>}

function ThemesAdmin({store}){const {draft,setDraft}=store;const apply=(name,p)=>setDraft(d=>({...d,theme:name,primary:p.primary,secondary:p.secondary,background:p.background,card:p.card,accent:p.accent,header:{...d.header,bg:p.primary},seasonFx:name!=='Padrão'}));return <div className="pad"><div className="theme-intro"><Sparkles/><div><h2>Temas pré-criados e animados</h2><p>Escolha um tema como base. Depois personalize cores, banners, fontes e elementos no Editor Visual. As animações aparecem na prévia antes da publicação.</p></div></div><div className="theme-grid">{Object.entries(themePresets).map(([name,p])=><div className={`theme-card ${draft.theme===name?'selected':''}`} key={name}><div className="theme-preview" style={{background:`linear-gradient(135deg,${p.primary},${p.secondary})`}}><span style={{background:p.accent}}>{p.symbols[0]}</span><b>{name}</b><small>{p.fx==='none'?'Sem animação':`Animação: ${p.fx}`}</small></div><div className="theme-swatches"><i style={{background:p.primary}}/><i style={{background:p.secondary}}/><i style={{background:p.accent}}/><i style={{background:p.background}}/></div><button onClick={()=>apply(name,p)}>{draft.theme===name?'Aplicado ao rascunho':'Usar este tema'}</button></div>)}</div><Panel title="Ajuste das animações"><label className="switch"><input type="checkbox" checked={draft.seasonFx} onChange={e=>setDraft(d=>({...d,seasonFx:e.target.checked}))}/> Ativar animação do tema</label><NumberControl label="Intensidade" value={draft.fxIntensity} min={8} max={50} onChange={v=>setDraft(d=>({...d,fxIntensity:v}))} suffix=" elementos"/><p className="muted">Os temas são camadas decorativas. O conteúdo e a hierarquia do catálogo não são alterados.</p></Panel></div>}

function Analytics({store}){const {analytics,draftProducts}=store;return <div className="pad"><div className="metrics"><Metric n={Object.values(analytics.views||{}).reduce((a,b)=>a+b,0)} t="Aberturas de produtos"/><Metric n={Object.values(analytics.searches||{}).reduce((a,b)=>a+b,0)} t="Pesquisas"/><Metric n={Object.values(analytics.departments||{}).reduce((a,b)=>a+b,0)} t="Acessos a departamentos"/><Metric n={Object.values(analytics.promotions||{}).reduce((a,b)=>a+b,0)} t="Acessos a promoções"/></div><div className="two"><Panel title="Produtos"><Ranking obj={analytics.views} labels={Object.fromEntries(draftProducts.map(p=>[p.code,p.name]))}/></Panel><Panel title="Departamentos"><Ranking obj={analytics.departments}/></Panel><Panel title="Pesquisas"><Ranking obj={analytics.searches}/></Panel><Panel title="Promoções"><Ranking obj={analytics.promotions}/></Panel></div></div>}
function SettingsAdmin({store}){const {draft,setDraft}=store;return <div className="pad"><div className="two"><Panel title="Identidade"><UploadControl label="Logo da empresa" value={draft.logoImage} onChange={v=>setDraft(d=>({...d,logoImage:v}))}/><UploadControl label="Ícone/Favicon" value={draft.faviconImage} onChange={v=>setDraft(d=>({...d,faviconImage:v}))}/><label>Nome da empresa<input value={draft.brand} onChange={e=>setDraft(d=>({...d,brand:e.target.value}))}/></label></Panel><Panel title="Arquitetura de produção"><ul className="spec"><li><b>Portal público:</b> www.empresa.com.br</li><li><b>Administrador:</b> admin.empresa.com.br</li><li><b>Banco:</b> Supabase PostgreSQL + Storage</li><li><b>Deploy:</b> GitHub → Cloudflare</li><li><b>Publicação:</b> rascunho separado da versão pública</li><li><b>Segurança:</b> Supabase Auth, RLS, rate limiting, logs e auditoria</li></ul></Panel></div><Panel title="Personalização avançada"><label>CSS personalizado<textarea rows="8" value={draft.customCss||''} onChange={e=>setDraft(d=>({...d,customCss:e.target.value}))} placeholder="Opcional: regras CSS avançadas para usuários técnicos."/></label></Panel></div>}

function App(){const store=useStore();const isAdmin=location.hostname.startsWith('admin.')||location.pathname.startsWith('/admin');return isAdmin?<AdminApp store={store}/>:<PublicPortal store={store}/>}
createRoot(document.getElementById('root')).render(<App/>);
